package com.mmt.controller;
import com.mmt.model.*; import com.mmt.repository.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/recommendations") @CrossOrigin(origins="*") public class RecommendationController { private final UserRepository users; private final HotelRepository hotels; private final FlightRepository flights; private final RecommendationFeedbackRepository feedback;
 public RecommendationController(UserRepository u,HotelRepository h,FlightRepository f,RecommendationFeedbackRepository fb){users=u;hotels=h;flights=f;feedback=fb;}
 @GetMapping public List<Map<String,Object>> get(@RequestParam Long userId){User u=users.findById(userId).orElseThrow(); String pref=(u.getPreferences()==null?"beach":u.getPreferences()).toLowerCase(); List<Map<String,Object>> out=new ArrayList<>(); var allFeedback=feedback.findAll(); for(Hotel h:hotels.findAll()){boolean beach=h.getCity().toLowerCase().contains("goa")||h.getCity().toLowerCase().contains("bali"); String why=beach&&pref.contains("beach")?"You liked beach destinations before.":"Matches your saved travel preferences and strong guest rating."; double community=allFeedback.stream().filter(x->"HOTEL".equalsIgnoreCase(x.getItemType())&&x.getItemId().equals(h.getId())).mapToDouble(x->x.isHelpful()?0.08:-0.05).sum(); double score=Math.max(0.45,Math.min(0.99,(beach&&pref.contains("beach")?0.86:0.68)+community)); out.add(Map.of("itemType","HOTEL","itemId",h.getId(),"title",h.getName(),"city",h.getCity(),"price",h.getCurrentPrice(),"why",why+" Community feedback is also considered.","score",score));} for(Flight f:flights.findAll()){boolean match=f.getDestinationCity().toLowerCase().contains((u.getFavoriteDestination()==null?"goa":u.getFavoriteDestination()).toLowerCase()); double community=allFeedback.stream().filter(x->"FLIGHT".equalsIgnoreCase(x.getItemType())&&x.getItemId().equals(f.getId())).mapToDouble(x->x.isHelpful()?0.08:-0.05).sum(); double score=Math.max(0.45,Math.min(0.99,(match?0.84:0.66)+community)); out.add(Map.of("itemType","FLIGHT","itemId",f.getId(),"title",f.getAirline()+" "+f.getFlightNumber(),"city",f.getDestinationCity(),"price",f.getPrice(),"why",match?"You often explore this destination.":"Matches your travel activity and current fare.","score",score));} out.sort((a,b)->Double.compare((Double)b.get("score"),(Double)a.get("score"))); if(out.size()>6)out=new ArrayList<>(out.subList(0,6)); return out; }
 @GetMapping("/user/{userId}") public List<Map<String,Object>> getAlias(@PathVariable Long userId){ return get(userId); }
 @PostMapping("/feedback") public RecommendationFeedback fb(@RequestBody RecommendationFeedback f){f.setCreatedAt(LocalDateTime.now());return feedback.save(f);}
}
